{
  "findings": [
    {
      "check_id": "CKV_AZURE_104",
      "title": "SQL Server Security Alert Policy has critical alerts disabled",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "HIGH",
      "explanation": "The configuration explicitly disables 'Sql_Injection' and 'Data_Exfiltration' alerts, which are critical security threats. This prevents detection of malicious database activities."
    },
    {
      "check_id": "CKV_AZURE_105",
      "title": "SQL Server Security Alert Policy retention days is less than 365",
      "resource": "azurerm_mssql_server_security_alert_policy.recovery_db_alerts",
      "severity": "MEDIUM",
      "explanation": "The retention_days is set to 20, which is below the recommended minimum of 365 days for audit logs and security alerts, potentially hindering long-term forensic analysis."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server_security_alert_policy\" \"recovery_db_alerts\" {\n  resource_group_name        = azurerm_resource_group.dr_platform.name\n  server_name                = azurerm_mssql_server.recovery_sql_server.name\n  state                      = \"Enabled\"\n  storage_endpoint           = azurerm_storage_account.backup_storage.primary_blob_endpoint\n  storage_account_access_key = azurerm_storage_account.backup_storage.primary_access_key\n  disabled_alerts = []\n  retention_days = 365\n}",
  "fix_summary": "Removed 'Sql_Injection' and 'Data_Exfiltration' from the disabled_alerts list to ensure these critical security alerts are enabled. Increased retention_days from 20 to 365 to meet standard compliance requirements for log retention."
}
